import numpy as np
import pytest
from numpy.testing import assert_array_equal

import pandas as pd
from pandas import concat


def test_concat_empty_series_axis_1():
    ser1 = pd.Series(np.arange(3), index=["a", "b", "c"])
    ser2 = pd.Series(np.arange(2), index=["d", "e"])

    result = concat([ser1, ser2], axis=1)
    expected = pd.DataFrame({"a": [0, 1, 2], "d": [np.nan, np.nan]})

    assert_array_equal(result, expected)
